To integrate mentions into your existing `SimpleEditor.vue` component, you'll need to modify the script section to import the necessary Tiptap extensions and configure them accordingly. Here's how you can incorporate mentions:

1. **Import Required Extensions**: Import the `Mention`, `Document`, `Paragraph`, and `Text` extensions from Tiptap.
2. **Configure the Mention Extension**: Set up the mention extension with the necessary configuration, such as `HTMLAttributes` and the `suggestion` function.

Below is the updated `SimpleEditor.vue` with the mention integration:

```vue /shared/codx-junior/client/src/components/tiptap/SimpleEditor.vue
<template>
  <div v-if="editor">
    <editor-content :editor="editor" />
  </div>
</template>

<script>
import StarterKit from '@tiptap/starter-kit'
import Document from '@tiptap/extension-document'
import Mention from '@tiptap/extension-mention'
import Paragraph from '@tiptap/extension-paragraph'
import Text from '@tiptap/extension-text'
import { Editor, EditorContent } from '@tiptap/vue-3'
import suggestion from './suggestion.js'

export default {
  components: {
    EditorContent,
  },

  props: {
    modelValue: {
      type: String,
      default: '',
    },
  },

  emits: ['update:modelValue'],

  data() {
    return {
      editor: null,
    }
  },

  watch: {
    modelValue(value) {
      const isSame = this.editor.getHTML() === value

      if (isSame) {
        return
      }

      this.editor.commands.setContent(value)
    },
  },

  mounted() {
    this.editor = new Editor({
      extensions: [
        StarterKit,
        Document,
        Paragraph,
        Text,
        Mention.configure({
          HTMLAttributes: {
            class: 'mention',
          },
          suggestion,
        }),
      ],
      content: this.modelValue,
      onUpdate: () => {
        this.$emit('update:modelValue', this.editor.getHTML())
      },
    })
  },

  beforeUnmount() {
    this.editor.destroy()
  },
}
</script>

<style lang="scss">
